import sys

def product_brute(nums):
    n = len(nums)
    res = [1] * n
    for i in range(n):
        for j, x in enumerate(nums):
            if i != j: res[i] *= x
    return res

if __name__ == '__main__':
    data = sys.stdin.read().split()
    if not data:
        sys.exit(0)
    n = int(data[0])
    nums = list(map(int, data[1:1 + n]))
    print(' '.join(map(str, product_brute(nums))))
